import{_ as o,l as s,o as e,c as l,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"Snort / Suricata 规则","description":"","frontmatter":{"title":"Snort / Suricata 规则","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ids-rules.md","filePath":"cs/ids-rules.md","lastUpdated":1789023840000}'),h={name:"cs/ids-rules.md"};function u(E,a,_,m,S,A){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="snort-suricata-规则" tabindex="-1">Snort / Suricata 规则 <a class="header-anchor" href="#snort-suricata-规则" aria-label="Permalink to &quot;Snort / Suricata 规则&quot;">​</a></h1><div class="epigraph"><p>规则把协议字段、内容匹配与流状态写成可部署的谓词。写得好能抓住已知形态；写得太宽则误杀。规则是知识压缩，不是应用规格。</p><footer>—— 据 Snort Users Manual 对规则语言；Suricata 对规则兼容的陈述</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/ids-ips">IDS/IPS</a>给了盒子。缺口是<strong>规则怎么写才算合同</strong>：协议、端口、内容、流。本课讲形态与维护，不提供针对特定 CVE 的利用匹配教程。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>特征规则对已知利用有效，对加密与变形弱。缺口是：版本管理、测试流量、禁用噪声规则。Emerging Threats 一类社区集要审查后启用。</p><h3 id="内容匹配的限度" tabindex="-1">内容匹配的限度 <a class="header-anchor" href="#内容匹配的限度" aria-label="Permalink to &quot;内容匹配的限度&quot;">​</a></h3><p>多态与编码让字节特征老化。协议状态比裸字符串稳。</p><p><span class="marginnote">Snort 规则语法公开。课程禁止用规则开发当攻击演练。蜜罐下一课提供另一类观测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读一条规则的头与选项（概念：msg、flow、content）。对照 Suricata 多线程。下一课蜜罐。</p>',12)),(e(),n(p,null,{default:r(()=>[c(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20HDR%5B%22%E5%8D%8F%E8%AE%AE%E4%B8%8E%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20OPT%5B%22%E5%86%85%E5%AE%B9%E4%B8%8E%E6%B5%81%E9%80%89%E9%A1%B9%22%5D%0A%20%20OPT%20--%3E%20ALERT%5B%22%E5%91%8A%E8%AD%A6%E6%88%96%E4%B8%A2%E5%BC%83%22%5D%0A%20%20OPT%20--%3E%20TUNE%5B%22%E6%B5%8B%E8%AF%95%E5%87%8F%E5%B0%91%E8%AF%AF%E6%8A%A5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>签名是过时的知识。要与威胁情报和下下一课 ATT&amp;CK 映射，否则规则集膨胀。蜜罐提供低误报的触点。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写针对生产的攻击规则。蜜罐下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IDS 要规则才认识形态。</li><li>协议状态优于裸字符串；要测试误报。</li><li>加密与变形让特征老化。</li><li>下一课蜜罐。</li><li>出处：Snort Users Manual；Suricata 文档。</li></ul>',8))])}const B=o(h,[["render",u]]);export{T as __pageData,B as default};
